CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "patients" ("id" integer primary key autoincrement not null, "full_name" varchar not null, "date_of_birth" date, "gender" varchar check ("gender" in ('male', 'female')), "phone" varchar, "phone_secondary" varchar, "city" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, "id_number" varchar, "occupation" varchar);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime, "price" numeric default '0');
CREATE TABLE IF NOT EXISTS "procedures" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "default_duration" integer not null default '30', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "branches" ("id" integer primary key autoincrement not null, "name" varchar not null, "address" varchar, "phone" varchar, "email" varchar, "notes" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default ('secretary'), "is_active" tinyint(1) not null default ('1'), "branch_id" integer, foreign key("branch_id") references "branches"("id") on delete set null);
