CREATE TABLE IF NOT EXISTS "eye_examinations" ("id" integer primary key autoincrement not null, "operation_id" integer not null, "examination_type" varchar check ("examination_type" in ('pre_op', 'post_op')) not null default 'pre_op', "od_lids" varchar, "od_conjunctiva" varchar, "od_cornea" varchar, "od_tbut" varchar, "od_schirmer" varchar, "od_anterior_chamber" varchar, "od_iris_pupil" varchar, "od_lens" varchar, "od_vitreous" varchar, "od_optic_disc" varchar, "od_retina" varchar, "od_macula" varchar, "od_vessels" varchar, "od_fom" varchar, "od_findings" text, "os_lids" varchar, "os_conjunctiva" varchar, "os_cornea" varchar, "os_tbut" varchar, "os_schirmer" varchar, "os_anterior_chamber" varchar, "os_iris_pupil" varchar, "os_lens" varchar, "os_vitreous" varchar, "os_optic_disc" varchar, "os_retina" varchar, "os_macula" varchar, "os_vessels" varchar, "os_fom" varchar, "os_findings" text, "unaided_od" varchar, "unaided_os" varchar, "manifest_refraction_od" text, "manifest_refraction_os" text, "cyclo_refraction_od" text, "cyclo_refraction_os" text, "notes" text, "created_at" datetime, "updated_at" datetime, "od_iop" varchar, "os_iop" varchar, foreign key("operation_id") references "operations"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "ectasia_risk_assessments" ("id" integer primary key autoincrement not null, "operation_id" integer not null, "pta_percentage_od" numeric, "pta_percentage_os" numeric, "rsb_od" numeric, "rsb_os" numeric, "tomography_normal_pattern" tinyint(1) not null default '0', "tomography_other" text, "pachymetry_thinnest_od" integer, "pachymetry_thinnest_os" integer, "notes" text, "created_at" datetime, "updated_at" datetime, "tomography_status" varchar check ("tomography_status" in ('normal', 'suspicious', 'other')), foreign key("operation_id") references "operations"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "operation_details" ("id" integer primary key autoincrement not null, "operation_id" integer not null, "femto_lasik" tinyint(1) not null default '0', "prk_mmc" tinyint(1) not null default '0', "prk_type" varchar check ("prk_type" in ('Alcohol 20%', 'Trans-PRK', 'Brush')), "trans_prk" tinyint(1) not null default '0', "ptk" tinyint(1) not null default '0', "topography_guided" tinyint(1) not null default '0', "excimer_profile" varchar check ("excimer_profile" in ('WFO', 'Topography Guided', 'Custom', 'Other')), "mmc_concentration" numeric, "mmc_duration_seconds" integer, "bll" tinyint(1) not null default '0', "drops_used" text, "target_refraction_od" text, "target_refraction_os" text, "mv_eye" varchar, "has_complications" tinyint(1) not null default '0', "complications_details" text, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("operation_id") references "operations"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "operation_approvals" ("id" integer primary key autoincrement not null, "operation_id" integer not null, "approved_by" integer not null, "approval_type" varchar check ("approval_type" in ('medical_clearance', 'surgical_approval', 'anesthesia_approval', 'final_approval')) not null default 'medical_clearance', "status" varchar check ("status" in ('pending', 'approved', 'rejected')) not null default 'pending', "comments" text, "approval_date" date, "created_at" datetime, "updated_at" datetime, foreign key("operation_id") references "operations"("id") on delete cascade, foreign key("approved_by") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "appointments" ("id" integer primary key autoincrement not null, "patient_id" integer not null, "doctor_id" integer not null, "category_id" integer, "procedure_id" integer, "appointment_date" date not null, "appointment_time" time not null, "duration" integer not null default ('30'), "notes" text, "notify_patient_sms" tinyint(1) not null default ('0'), "notify_doctor_sms" tinyint(1) not null default ('0'), "notify_doctor_email" tinyint(1) not null default ('0'), "follow_up" tinyint(1) not null default ('0'), "status" varchar not null default ('scheduled'), "created_at" datetime, "updated_at" datetime, "created_by" integer, "branch_id" integer, "visit_stage" varchar, "visit_type" varchar, "operation_id" integer, "price" numeric default '0', foreign key("branch_id") references branches("id") on delete set null on update no action, foreign key("created_by") references users("id") on delete set null on update no action, foreign key("patient_id") references patients("id") on delete cascade on update no action, foreign key("doctor_id") references doctors("id") on delete cascade on update no action, foreign key("category_id") references categories("id") on delete set null on update no action, foreign key("procedure_id") references procedures("id") on delete set null on update no action, foreign key("operation_id") references "operations"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "invoices" ("id" integer primary key autoincrement not null, "invoice_number" varchar not null, "patient_id" integer not null, "appointment_id" integer, "doctor_id" integer, "branch_id" integer, "invoice_date" date not null, "due_date" date, "subtotal" numeric not null default ('0'), "discount" numeric not null default ('0'), "tax" numeric not null default ('0'), "total_amount" numeric not null default ('0'), "paid_amount" numeric not null default ('0'), "remaining_amount" numeric not null default ('0'), "status" varchar not null default ('pending'), "payment_method" varchar, "notes" text, "created_by" integer, "created_at" datetime, "updated_at" datetime, "operation_id" integer, foreign key("created_by") references users("id") on delete set null on update no action, foreign key("branch_id") references branches("id") on delete set null on update no action, foreign key("doctor_id") references doctors("id") on delete set null on update no action, foreign key("appointment_id") references appointments("id") on delete set null on update no action, foreign key("patient_id") references patients("id") on delete cascade on update no action, foreign key("operation_id") references "operations"("id") on delete set null);
